/**
 * Impact effects -- hit sparks and bursts that play ON a target rather than
 * belonging to any one actor. Authored in art/effects/, keyed by file name.
 */
export interface EffectStrip {
  id: string;
  src: string;
  frames: number;
  /** width / height of ONE frame. */
  aspect: number;
}

